package io.mark.hitsplats;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class HitsplatStylesPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(HitsplatStylesPlugin.class);
		RuneLite.main(args);
	}
}

package io.mark.hitsplats.overlay;

import io.mark.hitsplats.art.HitsplatSkin;
import io.mark.hitsplats.art.HitsplatSprites;
import io.mark.hitsplats.art.HitsplatStyle;
import io.mark.hitsplats.HitsplatStylesPlugin;
import io.mark.hitsplats.combat.CombatStyle;
import io.mark.hitsplats.config.HitsplatIconSet;
import io.mark.hitsplats.config.HitsplatStylesConfig;
import io.mark.hitsplats.config.HitsplatTint;
import io.mark.hitsplats.hit.HitsplatTracker;
import io.mark.hitsplats.hit.TrackedHitsplat;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class HitsplatStylesOverlay extends Overlay
{
	private static final int[] SLOT_OFFSET = {0, 0, 0, -20, -15, -10, 15, -10, 15, 10, 0, 20, -15, 10, -30, -10};

	private static final int ICON_GAP = 4;

	private static final int DISPLAY_CYCLES = 70;
	private static final int NATIVE_SPLAT_TOP = -12;
	private static final int NATIVE_SPLAT_PAD = 1;
	private static final int DAMAGE_BASELINE = 15;


	private static final int FLOAT_DISTANCE = 12;

	private final Client client;
	private final HitsplatTracker tracker;
	private final HitsplatStylesConfig config;
	private final HitsplatSprites sprites;
	private final NpcHeights npcHeights;

	@Inject
	private HitsplatStylesOverlay(Client client, HitsplatTracker tracker, HitsplatStylesConfig config, HitsplatSprites sprites, NpcHeights npcHeights)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		this.sprites = sprites;
		this.npcHeights = npcHeights;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<Actor, List<TrackedHitsplat>> tracked = tracker.getTracked();
		if (tracked.isEmpty())
		{
			return null;
		}

		HitsplatStyle style = config.style();
		HitsplatStyle blockStyle = style == HitsplatStyle.OSRS ? config.blockArt().getStyle() : null;
		Frame frame = new Frame(client.getGameCycle(), style, blockStyle, config.tint(),
			config.hideBlockedDamage(), config.hideBlockedIcon(), config.iconSet(), config.shadows(),
			config.fadeOut() ? config.fadeLength() : 0);

		Font font = graphics.getFont();
		Composite composite = graphics.getComposite();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		frame.fontMetrics = graphics.getFontMetrics();

		for (Iterator<Map.Entry<Actor, List<TrackedHitsplat>>> it = tracked.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Actor, List<TrackedHitsplat>> entry = it.next();
			Actor actor = entry.getKey();
			List<TrackedHitsplat> splats = entry.getValue();

			boolean anyLeft = false;
			for (int i = 0; i < splats.size(); i++)
			{
				TrackedHitsplat splat = splats.get(i);
				if (splat == null || frame.cycle >= splat.getEndCycle() + frame.fadeLength)
				{
					continue;
				}

				anyLeft = true;
				if (!HitsplatStylesPlugin.DEBUG_SLOTS && splat.getSkin() != null && splat.getEndCycle() - DISPLAY_CYCLES <= frame.cycle)
				{
					renderHitsplat(graphics, actor, splat, frame);
				}
			}

			if (HitsplatStylesPlugin.DEBUG_SLOTS)
			{
				drawSlots(graphics, actor, splats);
			}

			if (!anyLeft)
			{
				it.remove();
			}
		}

		graphics.setFont(font);
		graphics.setComposite(composite);
		return null;
	}

	private void renderHitsplat(Graphics2D graphics, Actor actor, TrackedHitsplat splat, Frame frame)
	{
		HitsplatSkin skin = splat.getSkin();
		switch (frame.tint)
		{
			case NEVER:
				skin = skin.untinted();
				break;
			case ALWAYS:
				skin = skin.tinted();
				break;
			default:
				break;
		}

		HitsplatStyle style = splat.isBlock() && frame.blockStyle != null ? frame.blockStyle : frame.style;

		BufferedImage image = sprites.get(style, skin);
		if (image == null)
		{
			return;
		}

		Point anchor = anchor(actor);
		if (anchor == null)
		{
			return;
		}

		String text = splat.getText();

		CombatStyle iconStyle = null;
		BufferedImage icon = null;
		if (!(frame.hideBlockedIcon && splat.isBlock()))
		{
			iconStyle = splat.getCombatStyle();
			icon = sprites.getIcon(frame.iconSet, iconStyle);
			if (icon == null)
			{
				iconStyle = CombatStyle.MELEE;
				icon = sprites.getIcon(frame.iconSet, iconStyle);
			}
		}

		int overrun = frame.cycle - splat.getEndCycle();

		int animationY = 0;
		int alpha = 255;
		if (overrun >= 0 && frame.fadeLength > 0)
		{
			animationY = -(FLOAT_DISTANCE * overrun / frame.fadeLength);
			alpha = ((frame.fadeLength - overrun) << 8) / frame.fadeLength;
		}

		alpha = Math.max(0, Math.min(255, alpha));

		int slot = Math.min(splat.getSlot() << 1, SLOT_OFFSET.length - 2);
		int splatX = anchor.getX() + SLOT_OFFSET[slot] - image.getWidth() / 2 + NATIVE_SPLAT_PAD;
		int top = anchor.getY() + SLOT_OFFSET[slot | 1] + NATIVE_SPLAT_TOP + animationY;
		int centerY = top + image.getHeight() / 2;

		graphics.setComposite(alpha >= 255
			? AlphaComposite.SrcOver
			: AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha / 255f));

		BufferedImage splatShadow = frame.shadows && style.isShadowed() ? sprites.getShadow(style, skin) : null;
		if (splatShadow != null)
		{
			graphics.drawImage(splatShadow,
				splatX - (splatShadow.getWidth() - image.getWidth()) / 2,
				top - (splatShadow.getHeight() - image.getHeight()) / 2,
				null);
		}

		graphics.drawImage(image, splatX, top, null);

		if (icon != null)
		{
			int slotRight = splatX - ICON_GAP;
			int slotCenterX = slotRight - sprites.getIconSlotWidth(frame.iconSet) / 2;
			int iconX = slotCenterX - icon.getWidth() / 2;
			int iconY = centerY - icon.getHeight() / 2;

			BufferedImage shadow = frame.shadows ? sprites.getIconShadow(frame.iconSet, iconStyle) : null;
			if (shadow != null)
			{
				graphics.drawImage(shadow,
					iconX - (shadow.getWidth() - icon.getWidth()) / 2,
					iconY - (shadow.getHeight() - icon.getHeight()) / 2,
					null);
			}

			graphics.drawImage(icon, iconX, iconY, null);
		}

		if (!(frame.hideBlockedDamage && splat.isBlock()))
		{
			int textX = splatX + (image.getWidth() - frame.fontMetrics.stringWidth(text)) / 2;
			int textY = top + DAMAGE_BASELINE + style.getTextOffsetY();

			graphics.setColor(Color.BLACK);
			graphics.drawString(text, textX + 1, textY + 3);
			graphics.setColor(Color.WHITE);
			graphics.drawString(text, textX, textY + 3);
		}
	}

	private void drawSlots(Graphics2D graphics, Actor actor, List<TrackedHitsplat> splats)
	{
		Point anchor = anchor(actor);
		if (anchor == null)
		{
			return;
		}

		graphics.setComposite(AlphaComposite.SrcOver);
		graphics.setColor(Color.MAGENTA);
		graphics.fillRect(anchor.getX() - 1, anchor.getY() - 1, 3, 3);

		for (int i = 0; i < 4; i++)
		{
			int x = anchor.getX() + SLOT_OFFSET[i << 1] - 12 + NATIVE_SPLAT_PAD;
			int y = anchor.getY() + SLOT_OFFSET[(i << 1) | 1] + NATIVE_SPLAT_TOP;

			graphics.setColor(i < splats.size() && splats.get(i) != null ? Color.GREEN : Color.GRAY);
			graphics.drawRect(x, y, 24, 23);
			graphics.drawString(String.valueOf(i), x + 1, y + 10);
		}

		int rulerX = anchor.getX() + 40;
		int zero = anchor.getY() + NATIVE_SPLAT_TOP;
		for (int offset = -30; offset <= 30; offset += 5)
		{
			boolean labelled = offset % 10 == 0;
			graphics.setColor(offset == 0 ? Color.CYAN : Color.YELLOW);
			graphics.drawLine(rulerX, zero + offset, rulerX + (labelled ? 10 : 5), zero + offset);

			if (labelled)
			{
				graphics.drawString(String.valueOf(offset), rulerX + 13, zero + offset + 4);
			}
		}
	}

	private Point anchor(Actor actor)
	{
		LocalPoint localPoint = actor.getLocalLocation();
		if (localPoint == null)
		{
			return null;
		}

		WorldView worldView = client.getWorldView(localPoint.getWorldView());
		if (worldView == null)
		{
			return null;
		}

		int base = actor.getLogicalHeight();
		if (actor instanceof NPC)
		{
			NPCComposition composition = ((NPC) actor).getComposition();
			if (composition != null)
			{
				int configured = npcHeights.get(composition.getId());
				if (configured != -1)
				{
					base = configured;
				}
			}
		}

		int height = (base + actor.getAnimationHeightOffset()) / 2;
		int ground = groundHeight(localPoint, worldView, actor.getFootprintSize());
		return Perspective.localToCanvas(client, localPoint.getWorldView(),
			localPoint.getX(), localPoint.getY(), ground - height);
	}

	private int groundHeight(LocalPoint point, WorldView worldView, int footprint)
	{
		int plane = worldView.getPlane();
		if (footprint == 0)
		{
			return worldView.getTileHeight(point.getX(), point.getY(), plane);
		}

		int half = footprint / 2;
		int x = point.getX();
		int y = point.getY();

		int lowTileX = ((x - half) >> 7) + 1;
		int lowTileY = ((y - half) >> 7) + 1;
		int highTileX = (x + half) >> 7;
		int highTileY = (y + half) >> 7;

		int ground = Integer.MAX_VALUE;
		for (int tileX = lowTileX; tileX <= highTileX; tileX++)
		{
			for (int tileY = lowTileY; tileY <= highTileY; tileY++)
			{
				ground = Math.min(ground, heightAt(worldView, tileX << 7, tileY << 7, plane));
			}
		}

		ground = Math.min(ground, heightAt(worldView, x, y, plane));
		ground = Math.min(ground, heightAt(worldView, x - half, y - half, plane));
		ground = Math.min(ground, heightAt(worldView, x - half, y + half, plane));
		ground = Math.min(ground, heightAt(worldView, x + half, y - half, plane));
		return Math.min(ground, heightAt(worldView, x + half, y + half, plane));
	}

	private int heightAt(WorldView worldView, int x, int y, int plane)
	{
		return worldView.getTileHeight(x, y, plane);
	}

	private static final class Frame
	{
		private final int cycle;
		private final HitsplatStyle style;
		private final HitsplatStyle blockStyle;
		private final HitsplatTint tint;
		private final boolean hideBlockedDamage;
		private final boolean hideBlockedIcon;
		private final HitsplatIconSet iconSet;
		private final boolean shadows;
		private final int fadeLength;
		private FontMetrics fontMetrics;

		private Frame(int cycle, HitsplatStyle style, HitsplatStyle blockStyle, HitsplatTint tint, boolean hideBlockedDamage, boolean hideBlockedIcon, HitsplatIconSet iconSet, boolean shadows, int fadeLength)
		{
			this.cycle = cycle;
			this.style = style;
			this.blockStyle = blockStyle;
			this.tint = tint;
			this.hideBlockedDamage = hideBlockedDamage;
			this.hideBlockedIcon = hideBlockedIcon;
			this.iconSet = iconSet;
			this.shadows = shadows;
			this.fadeLength = fadeLength;
		}
	}
}

package io.mark.hitsplats.overlay;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class NpcHeights
{
	private static final String RESOURCE = "/io/mark/hitsplats/npc_heights.tsv";

	private final ScheduledExecutorService executor;
	private volatile Map<Integer, Integer> heights = Collections.emptyMap();

	@Inject
	private NpcHeights(ScheduledExecutorService executor)
	{
		this.executor = executor;
	}

	public void load()
	{
		executor.execute(() -> heights = read());
	}

	public void clear()
	{
		heights = Collections.emptyMap();
	}

	public int get(int npcId)
	{
		Integer height = heights.get(npcId);
		return height == null ? -1 : height;
	}

	private static Map<Integer, Integer> read()
	{
		Map<Integer, Integer> parsed = new HashMap<>();

		InputStream in = NpcHeights.class.getResourceAsStream(RESOURCE);
		if (in == null)
		{
			log.warn("Missing npc height table {}", RESOURCE);
			return parsed;
		}

		try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.charAt(0) == '#')
				{
					continue;
				}

				String[] parts = line.split("\t");
				if (parts.length < 2)
				{
					continue;
				}

				parsed.put(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to read npc height table", e);
		}

		log.debug("Loaded {} npc heights", parsed.size());
		return parsed;
	}
}

package io.mark.hitsplats.art;

import net.runelite.api.HitsplatID;

public enum HitsplatSkin
{
	DAMAGE("damage_normal"),
	DAMAGE_TINTED("damage_tinted", "damage_normal"),
	DAMAGE_MAX("damage_max", "damage_normal"),
	BLOCK("block_normal"),
	BLOCK_TINTED("block_tinted", "block_normal"),
	POISON("poison_normal"),
	POISON_TINTED("poison_tinted", "poison_normal"),
	VENOM("venom_normal"),
	VENOM_TINTED("venom_tinted", "venom_normal"),
	DISEASE("disease_normal"),
	DISEASE_TINTED("disease_tinted", "disease_normal"),
	HEAL("heal_normal", "poison_normal"),
	HEAL_TINTED("heal_tinted", "heal_normal", "poison_tinted", "poison_normal"),
	CYAN("damage_cyan_normal", "damage_normal"),
	CYAN_TINTED("damage_cyan_tinted", "damage_cyan_normal", "damage_tinted", "damage_normal"),
	CYAN_MAX("damage_cyan_max", "damage_max", "damage_cyan_normal", "damage_normal"),
	ORANGE("damage_orange_normal", "damage_normal"),
	ORANGE_TINTED("damage_orange_tinted", "damage_orange_normal", "damage_tinted", "damage_normal"),
	ORANGE_MAX("damage_orange_max", "damage_max", "damage_orange_normal", "damage_normal"),
	YELLOW("damage_yellow_normal", "damage_normal"),
	YELLOW_TINTED("damage_yellow_tinted", "damage_yellow_normal", "damage_tinted", "damage_normal"),
	YELLOW_MAX("damage_yellow_max", "damage_max", "damage_yellow_normal", "damage_normal"),
	WHITE("damage_white_normal", "damage_normal"),
	WHITE_TINTED("damage_white_tinted", "damage_white_normal", "damage_tinted", "damage_normal"),
	WHITE_MAX("damage_white_max", "damage_max", "damage_white_normal", "damage_normal"),
	POISE("damage_poise_normal", "damage_normal"),
	POISE_TINTED("damage_poise_tinted", "damage_poise_normal", "damage_tinted", "damage_normal"),
	POISE_MAX("damage_poise_max", "damage_max", "damage_poise_normal", "damage_normal"),
	PRAYER_DRAIN("prayer_drain_normal", "damage_normal"),
	BLEED("bleed_normal", "damage_normal"),
	BURN("burn_normal", "poison_normal", "damage_normal"),
	CORRUPTION("corruption_normal", "damage_normal"),
	DOOM("doom_normal", "damage_normal"),
	SANITY_DRAIN("sanity_drain_normal", "damage_normal"),
	SANITY_RESTORE("sanity_restore_normal", "heal_normal", "poison_normal");

	private final String[] fileNames;

	HitsplatSkin(String... fileNames)
	{
		this.fileNames = fileNames;
	}

	public String[] getFileNames()
	{
		return fileNames;
	}

	public HitsplatSkin untinted()
	{
		switch (this)
		{
			case DAMAGE_TINTED:
				return DAMAGE;
			case BLOCK_TINTED:
				return BLOCK;
			case POISON_TINTED:
				return POISON;
			case VENOM_TINTED:
				return VENOM;
			case DISEASE_TINTED:
				return DISEASE;
			case HEAL_TINTED:
				return HEAL;
			case CYAN_TINTED:
				return CYAN;
			case ORANGE_TINTED:
				return ORANGE;
			case YELLOW_TINTED:
				return YELLOW;
			case WHITE_TINTED:
				return WHITE;
			case POISE_TINTED:
				return POISE;
			default:
				return this;
		}
	}

	public HitsplatSkin tinted()
	{
		switch (this)
		{
			case DAMAGE:
				return DAMAGE_TINTED;
			case BLOCK:
				return BLOCK_TINTED;
			case POISON:
				return POISON_TINTED;
			case VENOM:
				return VENOM_TINTED;
			case DISEASE:
				return DISEASE_TINTED;
			case HEAL:
				return HEAL_TINTED;
			case CYAN:
				return CYAN_TINTED;
			case ORANGE:
				return ORANGE_TINTED;
			case YELLOW:
				return YELLOW_TINTED;
			case WHITE:
				return WHITE_TINTED;
			case POISE:
				return POISE_TINTED;
			default:
				return this;
		}
	}

	public static boolean isBlock(int hitsplatType)
	{
		return hitsplatType == HitsplatID.BLOCK_ME
			|| hitsplatType == HitsplatID.BLOCK_OTHER
			|| hitsplatType == HitsplatID.DISEASE_BLOCKED;
	}

	public static boolean isSupported(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.BLOCK_ME:
			case HitsplatID.BLOCK_OTHER:
			case HitsplatID.POISON:
			case HitsplatID.VENOM:
			case HitsplatID.DISEASE:
			case HitsplatID.DISEASE_BLOCKED:
				return true;
			default:
				return false;
		}
	}

	public static HitsplatSkin forType(int hitsplatType, boolean onLocalPlayer)
	{
		switch (hitsplatType)
		{
			case HitsplatID.DAMAGE_ME:
				return DAMAGE;
			case HitsplatID.DAMAGE_MAX_ME:
				return DAMAGE_MAX;
			case HitsplatID.BLOCK_ME:
				return BLOCK;
			case HitsplatID.BLOCK_OTHER:
				return BLOCK_TINTED;
			case HitsplatID.DAMAGE_ME_CYAN:
				return CYAN;
			case HitsplatID.DAMAGE_OTHER_CYAN:
				return CYAN_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
				return CYAN_MAX;
			case HitsplatID.CYAN_UP:
			case HitsplatID.CYAN_DOWN:
				return onLocalPlayer ? CYAN : CYAN_TINTED;
			case HitsplatID.DAMAGE_ME_ORANGE:
				return ORANGE;
			case HitsplatID.DAMAGE_OTHER_ORANGE:
				return ORANGE_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
				return ORANGE_MAX;
			case HitsplatID.DAMAGE_ME_YELLOW:
				return YELLOW;
			case HitsplatID.DAMAGE_OTHER_YELLOW:
				return YELLOW_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
				return YELLOW_MAX;
			case HitsplatID.DAMAGE_ME_WHITE:
				return WHITE;
			case HitsplatID.DAMAGE_OTHER_WHITE:
				return WHITE_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
				return WHITE_MAX;
			case HitsplatID.DAMAGE_ME_POISE:
				return POISE;
			case HitsplatID.DAMAGE_OTHER_POISE:
				return POISE_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return POISE_MAX;
			case HitsplatID.POISON:
				return onLocalPlayer ? POISON : POISON_TINTED;
			case HitsplatID.VENOM:
				return onLocalPlayer ? VENOM : VENOM_TINTED;
			case HitsplatID.DISEASE:
				return onLocalPlayer ? DISEASE : DISEASE_TINTED;
			case HitsplatID.DISEASE_BLOCKED:
				return onLocalPlayer ? BLOCK : BLOCK_TINTED;
			case HitsplatID.HEAL:
				return onLocalPlayer ? HEAL : HEAL_TINTED;
			case HitsplatID.PRAYER_DRAIN:
				return PRAYER_DRAIN;
			case HitsplatID.BLEED:
				return BLEED;
			case HitsplatID.BURN:
				return BURN;
			case HitsplatID.CORRUPTION:
				return CORRUPTION;
			case HitsplatID.DOOM:
				return DOOM;
			case HitsplatID.SANITY_DRAIN:
				return SANITY_DRAIN;
			case HitsplatID.SANITY_RESTORE:
				return SANITY_RESTORE;
			case HitsplatID.DAMAGE_OTHER:
			default:
				return DAMAGE_TINTED;
		}
	}
}

package io.mark.hitsplats.art;

import io.mark.hitsplats.combat.CombatStyle;
import io.mark.hitsplats.config.HitsplatIconSet;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;

@Slf4j
@Singleton
public class HitsplatSprites
{
	private final ScheduledExecutorService executor;

	private static final String RESOURCE_ROOT = "/io/mark/hitsplats/";
	private static final String ICON_DIRECTORY = "style_icons";
	private static final int SHADOW_RADIUS = 2;
	private static final int SHADOW_ALPHA = 120;

	private volatile Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> packs;
	private volatile Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> packShadows;
	private volatile Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> icons;
	private volatile Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> iconShadows;
	private volatile Map<HitsplatIconSet, Integer> iconSlotWidths;

	@Inject
	private HitsplatSprites(ScheduledExecutorService executor)
	{
		this.executor = executor;
	}

	public void load()
	{
		executor.execute(() ->
		{
			Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> loaded = new EnumMap<>(HitsplatStyle.class);
			Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> loadedShadows = new EnumMap<>(HitsplatStyle.class);
			for (HitsplatStyle style : HitsplatStyle.values())
			{
				Map<HitsplatSkin, BufferedImage> pack = loadPack(style);
				loaded.put(style, pack);
				loadedShadows.put(style, outlinePack(pack));
			}

			Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> loadedIcons = new EnumMap<>(HitsplatIconSet.class);
			Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> loadedIconShadows = new EnumMap<>(HitsplatIconSet.class);
			Map<HitsplatIconSet, Integer> widths = new EnumMap<>(HitsplatIconSet.class);

			for (HitsplatIconSet set : HitsplatIconSet.values())
			{
				Map<CombatStyle, BufferedImage> setIcons = loadIcons(set);
				Map<CombatStyle, BufferedImage> shadows = new EnumMap<>(CombatStyle.class);
				int widest = 0;

				for (Map.Entry<CombatStyle, BufferedImage> entry : setIcons.entrySet())
				{
					shadows.put(entry.getKey(), outline(entry.getValue(), SHADOW_RADIUS, SHADOW_ALPHA));
					widest = Math.max(widest, entry.getValue().getWidth());
				}

				loadedIcons.put(set, setIcons);
				loadedIconShadows.put(set, shadows);
				widths.put(set, widest);
			}

			iconSlotWidths = widths;
			iconShadows = loadedIconShadows;
			icons = loadedIcons;
			packShadows = loadedShadows;
			packs = loaded;
		});
	}

	public void clear()
	{
		packs = null;
		packShadows = null;
		icons = null;
		iconShadows = null;
		iconSlotWidths = null;
	}

	public BufferedImage get(HitsplatStyle style, HitsplatSkin skin)
	{
		Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> loaded = packs;
		if (loaded == null)
		{
			return null;
		}

		Map<HitsplatSkin, BufferedImage> pack = loaded.get(style);
		return pack == null ? null : pack.get(skin);
	}

	public BufferedImage getShadow(HitsplatStyle style, HitsplatSkin skin)
	{
		Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> loaded = packShadows;
		if (loaded == null)
		{
			return null;
		}

		Map<HitsplatSkin, BufferedImage> pack = loaded.get(style);
		return pack == null ? null : pack.get(skin);
	}

	private static Map<HitsplatSkin, BufferedImage> outlinePack(Map<HitsplatSkin, BufferedImage> pack)
	{
		Map<HitsplatSkin, BufferedImage> shadows = new EnumMap<>(HitsplatSkin.class);
		// Skins share images through their fallback chains, so outline each distinct one once.
		Map<BufferedImage, BufferedImage> byImage = new IdentityHashMap<>();

		for (Map.Entry<HitsplatSkin, BufferedImage> entry : pack.entrySet())
		{
			shadows.put(entry.getKey(), byImage.computeIfAbsent(entry.getValue(),
				image -> outline(image, SHADOW_RADIUS, SHADOW_ALPHA)));
		}

		return shadows;
	}

	public BufferedImage getIcon(HitsplatIconSet set, CombatStyle style)
	{
		return lookup(icons, set, style);
	}

	public BufferedImage getIconShadow(HitsplatIconSet set, CombatStyle style)
	{
		return lookup(iconShadows, set, style);
	}

	public int getIconSlotWidth(HitsplatIconSet set)
	{
		Map<HitsplatIconSet, Integer> widths = iconSlotWidths;
		if (widths == null)
		{
			return 0;
		}

		Integer width = widths.get(set);
		return width == null ? 0 : width;
	}

	private static BufferedImage lookup(Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> loaded,
		HitsplatIconSet set, CombatStyle style)
	{
		if (loaded == null)
		{
			return null;
		}

		Map<CombatStyle, BufferedImage> pack = loaded.get(set);
		return pack == null ? null : pack.get(style);
	}

	private static Map<CombatStyle, BufferedImage> loadIcons(HitsplatIconSet set)
	{
		Map<CombatStyle, BufferedImage> pack = new EnumMap<>(CombatStyle.class);
		for (CombatStyle style : CombatStyle.values())
		{
			BufferedImage image = loadImage(ICON_DIRECTORY + "/" + set.getDirectory(), style.getFileName());
			if (image != null)
			{
				pack.put(style, trim(image));
			}
		}

		log.debug("Loaded {} of {} {} combat style icons", pack.size(), CombatStyle.values().length, set.getDirectory());
		return pack;
	}

	private static Map<HitsplatSkin, BufferedImage> loadPack(HitsplatStyle style)
	{
		Map<HitsplatSkin, BufferedImage> pack = new EnumMap<>(HitsplatSkin.class);
		Map<String, BufferedImage> byFileName = new HashMap<>();

		for (HitsplatSkin skin : HitsplatSkin.values())
		{
			for (String fileName : skin.getFileNames())
			{
				BufferedImage image;
				if (byFileName.containsKey(fileName))
				{
					image = byFileName.get(fileName);
				}
				else
				{
					image = loadImage(style.getDirectory(), fileName);
					byFileName.put(fileName, image);
				}

				if (image != null)
				{
					pack.put(skin, image);
					break;
				}
			}
		}

		log.debug("Loaded hitsplat style {}: {} of {} skins", style.getDirectory(), pack.size(), HitsplatSkin.values().length);
		return pack;
	}

	private static BufferedImage outline(BufferedImage image, int radius, int maxAlpha)
	{
		int width = image.getWidth() + radius * 2;
		int height = image.getHeight() + radius * 2;
		int[] alpha = new int[width * height];

		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) == 0)
				{
					continue;
				}

				for (int dy = -radius; dy <= radius; dy++)
				{
					for (int dx = -radius; dx <= radius; dx++)
					{
						double distance = Math.sqrt(dx * dx + dy * dy);
						if (distance > radius)
						{
							continue;
						}

						int value = (int) Math.round(maxAlpha * (1d - distance / (radius + 1d)));
						int index = (y + radius + dy) * width + x + radius + dx;
						if (value > alpha[index])
						{
							alpha[index] = value;
						}
					}
				}
			}
		}

		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		for (int index = 0; index < alpha.length; index++)
		{
			if (alpha[index] > 0)
			{
				out.setRGB(index % width, index / width, alpha[index] << 24);
			}
		}

		return out;
	}

	private static BufferedImage trim(BufferedImage image)
	{
		int minX = image.getWidth();
		int minY = image.getHeight();
		int maxX = -1;
		int maxY = -1;

		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) == 0)
				{
					continue;
				}

				minX = Math.min(minX, x);
				minY = Math.min(minY, y);
				maxX = Math.max(maxX, x);
				maxY = Math.max(maxY, y);
			}
		}

		if (maxX < 0 || (minX == 0 && minY == 0 && maxX == image.getWidth() - 1 && maxY == image.getHeight() - 1))
		{
			return image;
		}

		return image.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}

	private static BufferedImage loadImage(String directory, String fileName)
	{
		String path = RESOURCE_ROOT + directory + "/" + fileName + ".png";
		if (HitsplatSprites.class.getResource(path) == null)
		{
			return null;
		}

		try
		{
			return ImageUtil.loadImageResource(HitsplatSprites.class, path);
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to read hitsplat image {}", path, e);
			return null;
		}
	}
}

